-- Запустить в Supabase → SQL Editor.
-- ВНИМАНИЕ: публичные политики разрешают всем посетителям изменять и удалять события.
create table if not exists public.events(id bigint generated by default as identity primary key,title text not null,start_date date not null,end_date date not null,created_by text not null,leader text,location text,participants text,notes text,updated_by text,created_at timestamptz default now(),updated_at timestamptz default now(),constraint valid_dates check(end_date>=start_date));
create table if not exists public.deletion_logs(id bigint generated by default as identity primary key,event_id bigint,event_title text not null,deleted_by text not null,reason text not null,deleted_at timestamptz default now());
alter table public.events enable row level security;alter table public.deletion_logs enable row level security;
create policy "public read events" on public.events for select to anon,authenticated using(true);
create policy "public insert events" on public.events for insert to anon,authenticated with check(true);
create policy "public update events" on public.events for update to anon,authenticated using(true) with check(true);
create policy "public delete events" on public.events for delete to anon,authenticated using(true);
create policy "public read deletion logs" on public.deletion_logs for select to anon,authenticated using(true);
create policy "public insert deletion logs" on public.deletion_logs for insert to anon,authenticated with check(true);
-- В Supabase Dashboard также включите Realtime для таблицы events (Database → Publications).
